import{_ as s,C as o,o as r,c as d,j as t,a as n,b as l,w as a,E as c,a1 as u,a0 as p}from"./chunks/framework.DzvPB4Y-.js";const w=JSON.parse('{"title":"From Business Examples to Your Application","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/integration.md","filePath":"frameworks/integration.md"}'),h={name:"frameworks/integration.md"};function m(b,e,g,f,k,v){const i=o("Mermaid");return r(),d("div",null,[e[1]||(e[1]=t("h1",{id:"from-business-examples-to-your-application",tabindex:"-1"},[n("From Business Examples to Your Application "),t("a",{class:"header-anchor",href:"#from-business-examples-to-your-application","aria-label":'Permalink to "From Business Examples to Your Application"'},"​")],-1)),e[2]||(e[2]=t("p",null,"After a first lesson, keep the small example application before adding an HTTP service: read one fixed input, make one real framework call and print independently checkable results. Add databases, queues and UI after input mapping, outcomes and error handling are stable.",-1)),e[3]||(e[3]=t("h2",{id:"_1-keep-the-shortest-path",tabindex:"-1"},[n("1. Keep the Shortest Path "),t("a",{class:"header-anchor",href:"#_1-keep-the-shortest-path","aria-label":'Permalink to "1. Keep the Shortest Path"'},"​")],-1)),(r(),l(u,null,{default:a(()=>[c(i,{id:"mermaid-9",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5BOrder%20and%20resource%20snapshot%5D%20--%3E%20B%5BBusiness%20mapping%20and%20unit%20checks%5D%0A%20%20%20%20B%20--%3E%20C%5BDomain%20problem%20and%20configuration%5D%0A%20%20%20%20C%20--%3E%20D%5BFramework%20and%20solver%20backend%5D%0A%20%20%20%20D%20--%3E%20E%5BTerminal%20and%20domain%20validation%5D%0A%20%20%20%20E%20--%3E%20F%5BBusiness%20result%20and%20audit%20record%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=p('<p>This is an application responsibility diagram, not a shared callable API. Framework entry points and return types differ. Do not discard original reports, quantities or errors to force them into a uniform interface.</p><table tabindex="0"><thead><tr><th>Layer</th><th>Include</th><th>Keep out</th></tr></thead><tbody><tr><td>Input adapter</td><td>Explicit conversion of order IDs, units, time, stock and resources</td><td>Silent zeros, dropped orders or merging distinct IDs by dimensions</td></tr><tr><td>Application orchestration</td><td>Domain problem, configuration, backend, budgets and extension wiring</td><td>A second implementation of existing conservation or overlap constraints</td></tr><tr><td>Business rules</td><td>Single-candidate policies or global modeling extensions</td><td>Discovering hard-rule violations only during report export</td></tr><tr><td>Output adapter</td><td>Validated plan, status, metrics, shortfalls and diagnostics</td><td>Presenting mocks, empty render objects or no-incumbent terminals as plans</td></tr></tbody></table><h2 id="_2-change-five-things-in-order" tabindex="-1">2. Change Five Things in Order <a class="header-anchor" href="#_2-change-five-things-in-order" aria-label="Permalink to &quot;2. Change Five Things in Order&quot;">​</a></h2><ol><li><strong>Retain the hand-checkable baseline:</strong> run the first-lesson business function and main before importing production orders.</li><li><strong>Confirm the execution path:</strong> real backend examples need real backends; preserve heuristic semantics where documented. Connect both RMP and final phases for BPP2D/BPP3D, not preset prices or usages.</li><li><strong>Handle request-boundary errors:</strong> translate CLI errors into structured server responses and retain reports for normal no-solution terminals. Entry points have different return types.</li><li><strong>Replace one data category at a time:</strong> demand, then resources, then rules, preserving independently checkable invariants.</li><li><strong>Add infrastructure last:</strong> databases, queues and UI; reject stale outputs and redact credentials and licenses from diagnostics.</li></ol><p>Configure dependencies and native libraries using <a href="./setup.html">Setup</a>. First-lesson sources include imports; similarly named Kotlin/Rust constructors are not interchangeable.</p><h2 id="_3-check-input-before-modeling" tabindex="-1">3. Check Input Before Modeling <a class="header-anchor" href="#_3-check-input-before-modeling" aria-label="Permalink to &quot;3. Check Input Before Modeling&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Input</th><th>Business decision required</th></tr></thead><tbody><tr><td>IDs and references</td><td>Unique identities and existing product, container, resource and node references</td></tr><tr><td>Counts and units</td><td>Integer pieces/rolls, explicit length/weight conversions and zero-demand treatment</td></tr><tr><td>Stock and bounds</td><td>Meaning of absent stock; distinguish <code>null</code>, zero and a missing field</td></tr><tr><td>Time and calendars</td><td>Time zone, allowed starts, intervals, frozen choices and execution facts</td></tr><tr><td>Objective</td><td>Priority of count, consumption, cost or service level, with explicit weight normalization</td></tr><tr><td>Budgets</td><td>Candidate, node, iteration and total-time limits, including how partial results are displayed</td></tr></tbody></table><p>Do not invent cancellation support where an entry point does not provide it; check backend capabilities. Prevent a cancelled or stale run from overwriting a newer schedule.</p><h2 id="_4-success-still-requires-two-outcome-checks" tabindex="-1">4. Success Still Requires Two Outcome Checks <a class="header-anchor" href="#_4-success-still-requires-two-outcome-checks" aria-label="Permalink to &quot;4. Success Still Requires Two Outcome Checks&quot;">​</a></h2><p>Outer success means a report or result was returned. It may still describe infeasibility, a time limit without an incumbent, a time-limited incumbent or optimality. Read the actual language-specific fields and enums.</p><table tabindex="0"><thead><tr><th>Observation</th><th>Application action</th></tr></thead><tbody><tr><td>Input or technical error</td><td>Return a locatable error; do not present an old plan as this run&#39;s success</td></tr><tr><td>Normal terminal without a deliverable</td><td>Show diagnostics; distinguish full-problem infeasibility from an insufficient pool</td></tr><tr><td>An incumbent exists</td><td>Validate business feasibility and retain its real terminal status</td></tr><tr><td>Current model proven optimal</td><td>Preserve model scope, candidate completeness, custom rules and evidence source</td></tr><tr><td>Geometry, stock or process validation fails</td><td>Do not deliver; retain input/report and inspect modeling or extraction</td></tr></tbody></table><p>A business response should retain request/input revision, configuration, actual backend, deliverability, original terminal, objective with units, plan, shortfalls and diagnostics. <strong>This is an application design recommendation, not a common OSPF serialization schema.</strong> Missing bounds/gaps remain unavailable, not zero.</p><h2 id="_5-protect-integration-with-three-test-groups" tabindex="-1">5. Protect Integration with Three Test Groups <a class="header-anchor" href="#_5-protect-integration-with-three-test-groups" aria-label="Permalink to &quot;5. Protect Integration with Three Test Groups&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>Examples</th><th>Acceptance</th></tr></thead><tbody><tr><td>Feasible baseline</td><td>One container, one pattern, two activities, four-node flow</td><td>Exact demand, geometry/process/conservation, resources and recomputed cost</td></tr><tr><td>Deliberately infeasible</td><td>Oversized item, frozen-calendar conflict, insufficient shared resource</td><td>No fabricated plan; correctly scoped conclusions</td></tr><tr><td>Boundaries and failures</td><td>Duplicate IDs, wrong units, zero stock, backend failure, no-incumbent time limit</td><td>No silent input changes; technical errors separate from business terminals</td></tr></tbody></table><p>Do not assert only the objective. Equivalent optima can differ in coordinates or activity order; prefer invariants and objective tolerances. Lock down a particular plan only when the business actually requires it.</p><p>Second-lesson hand calculations are exercises to implement, not production cases already executed in the repository. Linked contract tests demonstrate local capabilities, not the entire extended problem.</p><h2 id="_6-continue-with-a-concrete-scenario" tabindex="-1">6. Continue with a Concrete Scenario <a class="header-anchor" href="#_6-continue-with-a-concrete-scenario" aria-label="Permalink to &quot;6. Continue with a Concrete Scenario&quot;">​</a></h2><ul><li><a href="./bpp1d/business-scenario.html">BPP1D: container types, stock and cost</a></li><li><a href="./bpp2d/business-scenario.html">BPP2D: sheet types, rotation and spacing</a></li><li><a href="./bpp3d/business-scenario.html">BPP3D: bin types and objectives</a></li><li><a href="./csp1d/business-scenario.html">CSP1D: demand units and business rules</a></li><li><a href="./csp2d/business-scenario.html">CSP2D: kerf, cutting process and coils</a></li><li><a href="./gantt/business-scenario.html">Gantt: calendars and rolling recovery</a></li><li><a href="./network/business-scenario.html">Network: shared resources, shortage and embedding</a></li></ul><p>Determine rule ownership first: single-candidate rules belong in generation/policies; cross-candidate or cross-domain rules belong in a joint model. Use the <a href="/ospf/guide/modeling-workflow.html">modeling workflow</a> and <a href="/ospf/guide/solving-results.html">solver result guide</a>, rather than extending by copying the solve loop.</p>',19))])}const x=s(h,[["render",m]]);export{w as __pageData,x as default};
